/* @lc app=leetcode id=4058 lang=kotlin */ class Solution { fun maxValue(nums: IntArray): Long = nums.indices.runningFold(0L) { a, i -> a + (if (i % 2 == 0) nums[i] else -nums[i]) }.let { Q -> Q.last() + 2 * Q.indices.fold(Triple(Long.MIN_VALUE / 4, Long.MIN_VALUE / 4, 0L)) { (me, mo, best), y -> if (y % 2 == 0) Triple(maxOf(me, Q[y]), mo, maxOf(best, me - Q[y])) else Triple(me, maxOf(mo, Q[y]), maxOf(best, mo - Q[y])) }.third } }